func (q *Queries) UpsertInsight(ctx context.Context, arg UpsertInsightParams) error {
	_, err := q.db.Exec(ctx, upsertInsight,
		arg.ConversationID,
		arg.Summary,
		arg.Topic,
		arg.Sentiment,
		arg.IsComplaint,
		arg.Keywords,
		arg.Fingerprint,
		arg.Model,
		arg.AnalyzedAt,
	)
	return err
}

const upsertReplyTemplate = `-- name: UpsertReplyTemplate :exec
INSERT INTO sales.reply_templates (id, title, body, is_active, created_by) VALUES ($1, $2, $3, $4, $5)
ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, body = EXCLUDED.body, is_active = EXCLUDED.is_active, updated_at = now()
`

type UpsertReplyTemplateParams struct {
	ID        string
	Title     string
	Body      string
	IsActive  bool
	CreatedBy *string
}

func (q *Queries) UpsertReplyTemplate(ctx context.Context, arg UpsertReplyTemplateParams) error {
	_, err := q.db.Exec(ctx, upsertReplyTemplate,
		arg.ID,
		arg.Title,
		arg.Body,
		arg.IsActive,
		arg.CreatedBy,
	)
	return err
}
